-- Polestar.QuestDB: the quest database (load-on-demand addon Polestar_QuestDB,
-- generated by `forge data questdb`) and its lookup API.
-- Markers, available quests, tooltips and nameplate icons build on it
-- (Tracker.lua, Tooltips.lua). Record layouts: rust/crates/forge-data/src/questdb.rs.
--
-- Client calls Compat does not cover yet live in the small "client" block at
-- the bottom (quest log enumeration, completed-quest list); the pack itself
-- loads through Data.Pack, only while a quest feature wants it (Q.IsWanted).

local ADDON, ns = ...

local Q = {}
ns.QuestDB = Q

local type, pairs, tonumber = type, pairs, tonumber

ns.RegisterDefaults("qol", {
	questDB = true, -- load the quest database (Polestar_QuestDB) when a quest feature needs it
	mapObjectives = false, -- objective markers on the world map (off by default: crowded maps)
	minimapObjectives = false, -- ... and on the minimap
	objectiveAreas = false, -- a soft area under each objective spawn cluster (world map)
	turnInMarkers = false, -- markers on quest enders once a quest is ready
	availableQuests = false, -- markers on quest givers with quests you can take now
	lowLevelQuests = false, -- include grey (trivial) quests among available ones
	questLevelWindow = 5, -- available quests up to this many levels above yours (10: any)
	questTooltips = true, -- quest lines on unit, item and object tooltips
	nameplateIcons = false, -- quest icon on nameplates of objective mobs
	questLevels = true, -- "[12]" before quest titles the client lists without a level (gossip, greeting, details)
	guideHighlight = true, -- the active guide step's quests stand out on the maps
	guideDim = false, -- ... and every other quest marker dims while a guide runs
})

-- questLevelWindow at or above this shows any level.
Q.LEVEL_WINDOW_ANY = 10

Q.ADDON = "Polestar_QuestDB"

-- The records stay text: each kind is LuaChunks strings (Core/LuaChunks.lua, written by `forge data
-- questdb`), and a record is decoded when it is read, into a table the store's weak cache keeps while
-- someone holds it. data.<kind>[id] reads like the tables of schema 1; it cannot be iterated: Q.QuestIds.
local LuaChunks = ns.LuaChunks
local store = LuaChunks.New()
local byte, sub, find, gmatch, gsub, char = string.byte, string.sub, string.find, string.gmatch, string.gsub, string.char
local unpack, floor = unpack, math.floor

local function hex(h) return char(tonumber(h, 16)) end

-- The array size Lua 5.1 gives a table constructor of n items (NEWTABLE rounds it as a "floating point
-- byte": 19 -> 20). A record built with { unpack(t, 1, csize(n)) } has the array its schema-1 constructor
-- had, so # finds the same border when the record has nil holes.
local function csize(n)
	if n < 16 then return n end
	local e = 0
	while n >= 16 do
		n = floor((n + 1) / 2)
		e = e + 1
	end
	return n * 2 ^ e
end

-- A record's payload (forge-data questdb.rs `payload`) -> its positional table: fields by ";", empty for
-- nil, "'" and %XX-escaped text for a string, "{" and elements by "," for a list of numbers, else a number.
local vals, list = {}, {} -- scratch: every slot a record reads is written first
local function decode(s)
	local n = 0
	for f in gmatch(s .. ";", "([^;]*);") do
		n = n + 1
		local c = byte(f, 1)
		if c == 39 then -- '
			local text = sub(f, 2)
			if find(text, "%", 1, true) then text = gsub(text, "%%(%x%x)", hex) end
			vals[n] = text
		elseif c == 123 then -- {
			local m = 0
			for e in gmatch(sub(f, 2) .. ",", "([^,]*),") do
				m = m + 1
				list[m] = tonumber(e)
			end
			local size = csize(m)
			for i = m + 1, size do list[i] = nil end
			vals[n] = { unpack(list, 1, size) }
		else
			vals[n] = tonumber(f) -- nil when empty
		end
	end
	local size = csize(n)
	for i = n + 1, size do vals[i] = nil end
	return { unpack(vals, 1, size) }
end

local function view(kind)
	return setmetatable({}, {
		__index = function(_, id)
			if id == nil then return nil end
			return store:Get(kind, id, decode)
		end,
		__newindex = function() error("QuestDB: records are read-only") end,
	})
end

local data = { quests = view("quests"), npcs = view("npcs"), objects = view("objects"), items = view("items"), meta = nil }
Q._data = data
local questIds -- sorted, built on first ask

-- Called by the data addon's files: MapFrames.lua's counts, and each kind's chunks.
function Q.SetMeta(meta)
	if type(meta) == "table" then data.meta = meta end
end

function Q.AddChunk(kind, lo, hi, text)
	if rawget(data, kind) == nil or kind == "meta" or type(text) ~= "string" then return end
	store:Add(kind, lo, hi, text)
	if kind == "quests" then questIds = nil end
end

-- Every quest id in the database, ascending (the same table each call: do not change it).
function Q.QuestIds()
	if not questIds then questIds = store:Ids("quests") end
	return questIds
end

function Q.IsLoaded()
	return data.meta ~= nil
end

-- Loaded and switched on.
function Q.IsEnabled()
	return data.meta ~= nil and ns.Get("qol.questDB") and true or false
end

---------------------------------------------------------------------------
-- Raw records (internal; layouts in rust/crates/forge-data/src/questdb.rs)
---------------------------------------------------------------------------

local QUEST_TITLE, QUEST_LEVEL, QUEST_MIN, QUEST_RACES, QUEST_CLASSES, QUEST_FACTION = 1, 2, 3, 4, 5, 6
local QUEST_START, QUEST_FINISH, QUEST_START_ITEM, QUEST_PRE, QUEST_EXCL, QUEST_OBJ = 7, 8, 9, 10, 11, 12
local QUEST_ZONE, QUEST_EVENTS, QUEST_SKILL, QUEST_HOLIDAY, QUEST_PRE_ALL, QUEST_RACE_HIGH = 13, 14, 15, 16, 17, 18
local QUEST_ITEMS = 19
Q.F = {
	TITLE = QUEST_TITLE, LEVEL = QUEST_LEVEL, MIN = QUEST_MIN, RACES = QUEST_RACES, CLASSES = QUEST_CLASSES,
	FACTION = QUEST_FACTION, START = QUEST_START, FINISH = QUEST_FINISH, START_ITEM = QUEST_START_ITEM,
	PRE = QUEST_PRE, EXCL = QUEST_EXCL, OBJ = QUEST_OBJ, ZONE = QUEST_ZONE, EVENTS = QUEST_EVENTS,
	SKILL = QUEST_SKILL, HOLIDAY = QUEST_HOLIDAY, PRE_ALL = QUEST_PRE_ALL, RACE_HIGH = QUEST_RACE_HIGH,
	ITEMS = QUEST_ITEMS,
}
Q.KIND = { "kill", "item", "object", "event" }

function Q.QuestRecord(id) return data.quests[id] end
function Q.NpcRecord(id) return data.npcs[id] end
function Q.ObjectRecord(id) return data.objects[id] end
function Q.ItemRecord(id) return data.items[id] end

-- Whether quest questID hands over item itemID when it is taken (Bethor's
-- Scroll for Thule Ravenclaw; never a reward). Allocation-free.
function Q.HandsOver(questID, itemID)
	local r = data.quests[questID]
	local v = r and r[QUEST_ITEMS]
	if v == itemID then return true end
	if type(v) == "table" then
		for i = 1, #v do
			if v[i] == itemID then return true end
		end
	end
	return false
end

-- Whether quest questID uses item itemID without asking for it: the item is
-- in its handed-over field, which also holds the items its work needs (the
-- Sunscale Feather for the Scytheclaw nests, the Fresh Zhevra Carcass that
-- lures Ishamuhale), and no objective of it is that item, so no quest-log
-- line counts it. False while the database is not loaded. Allocation-free.
function Q.UsesOnly(questID, itemID)
	if not Q.HandsOver(questID, itemID) then return false end
	local obj = data.quests[questID][QUEST_OBJ]
	if obj then
		for i = 1, #obj, 3 do
			if obj[i] == 2 and obj[i + 1] == itemID then return false end
		end
	end
	return true
end

-- A ref is an NPC id (> 0) or an object id (< 0), as in start/finish lists.
local function entityRecord(ref)
	if ref > 0 then return data.npcs[ref] end
	return data.objects[-ref]
end
Q.EntityRecord = entityRecord

-- A name in the client's language where Polestar.Names has it, else the
-- database's English. kind: "Quest", "Npc", "Object" or "Item".
local function named(kind, id, english)
	local N = ns.Names
	return (N and N[kind](id)) or english
end

local function refName(ref, english)
	if ref > 0 then return named("Npc", ref, english) end
	return named("Object", -ref, english)
end

function Q.EntityName(ref)
	local rec = entityRecord(ref)
	return rec and refName(ref, rec[1]) or nil
end

-- fn(a, b, map, frame, x, y, r, clusterIndex) for every spawn cluster of a
-- ref; frame is "e" (Era) or nil (live). a, b are passed through so callers
-- need no closure. Returns the number of clusters.
function Q.EachSpawn(ref, fn, a, b)
	local rec = entityRecord(ref)
	if not rec then return 0 end
	local i, n, total = 2, #rec, 0
	while i + 2 <= n do
		local map, frame, count = rec[i], rec[i + 1], rec[i + 2]
		local f = frame == 0 and "e" or nil
		local j = i + 3
		for c = 1, count do
			total = total + 1
			fn(a, b, map, f, rec[j], rec[j + 1], rec[j + 2], c)
			j = j + 3
		end
		i = j
	end
	return total
end

function Q.HasSpawns(ref)
	local rec = entityRecord(ref)
	return rec ~= nil and #rec >= 7
end

-- Iterate a "one id or a list" field: for _, v in Q.Each(field) do ... end
local function eachNext(t, i)
	i = i + 1
	local v = t[i]
	if v ~= nil then return i, v end
end
local single = {}
local function eachSingle(v, i)
	if i == 0 then return 1, v end
end
function Q.Each(v)
	if type(v) == "table" then return eachNext, v, 0 end
	if v == nil then return eachNext, single, 0 end
	return eachSingle, v, 0
end
local Each = Q.Each

---------------------------------------------------------------------------
-- Lookup API (allocates its result; for UI and other modules)
---------------------------------------------------------------------------

local function refList(v)
	local npcs, objects = {}, {}
	for _, r in Each(v) do
		if r > 0 then npcs[#npcs + 1] = r else objects[#objects + 1] = -r end
	end
	return npcs, objects
end

local function idList(v)
	local out = {}
	for _, id in Each(v) do out[#out + 1] = id end
	return out
end

local FACTIONS = { "Alliance", "Horde" }

-- { id, title, level, minLevel, races, classes, faction ("Alliance"|"Horde"|nil),
--   start = { npc = {}, object = {}, item = {} }, finish = { npc = {}, object = {} },
--   pre = { ids } (any one completed unlocks it), preAll = { ids } (every one
--   needed; breadcrumbs are in neither), excl = { ids }, zone, skill, holiday,
--   objectives = { { kind = "kill"|"item"|"object"|"event", id, count, map, x, y, f }, ... } }
function Q.GetQuest(id)
	local r = data.quests[id]
	if not r then return nil end
	local sn, so = refList(r[QUEST_START])
	local fn, fo = refList(r[QUEST_FINISH])
	local q = {
		id = id, title = named("Quest", id, r[QUEST_TITLE]), level = r[QUEST_LEVEL], minLevel = r[QUEST_MIN],
		races = r[QUEST_RACES], classes = r[QUEST_CLASSES], faction = FACTIONS[r[QUEST_FACTION] or 0],
		start = { npc = sn, object = so, item = idList(r[QUEST_START_ITEM]) },
		finish = { npc = fn, object = fo },
		pre = idList(r[QUEST_PRE]), preAll = idList(r[QUEST_PRE_ALL]), excl = idList(r[QUEST_EXCL]),
		zone = r[QUEST_ZONE], skill = r[QUEST_SKILL], holiday = r[QUEST_HOLIDAY],
		objectives = {},
	}
	local obj, ev = r[QUEST_OBJ], r[QUEST_EVENTS]
	if obj then
		for i = 1, #obj, 3 do
			local kind, oid, count = obj[i], obj[i + 1], obj[i + 2]
			local o = { kind = Q.KIND[kind], id = oid, count = count }
			if kind == 4 then
				o.id = nil
				if ev and oid and oid > 0 then
					local k = (oid - 1) * 4
					o.map, o.f, o.x, o.y = ev[k + 1], ev[k + 2] == 0 and "e" or nil, ev[k + 3], ev[k + 4]
				end
			end
			q.objectives[#q.objectives + 1] = o
		end
	end
	return q
end

function Q.GetQuestTitle(id)
	local r = data.quests[id]
	return r and named("Quest", id, r[QUEST_TITLE]) or nil
end

local function spawnRow(list, _, map, f, x, y, r)
	list[#list + 1] = { map = map, f = f, x = x, y = y, r = r }
end

local function entityView(ref, id)
	local rec = entityRecord(ref)
	if not rec then return nil end
	local spawns = {}
	Q.EachSpawn(ref, spawnRow, spawns)
	return { id = id, name = refName(ref, rec[1]), spawns = spawns }
end

-- { id, name, spawns = { { map, x, y, r (yd), f ("e"|nil) }, ... } }
function Q.GetNpc(id) return id and entityView(id, id) or nil end
function Q.GetObject(id) return id and entityView(-id, id) or nil end

-- { { id, name, chance }, ... } best chance first, or nil.
function Q.GetItemDroppers(itemID)
	local rec = itemID and data.items[itemID]
	if not rec then return nil end
	local n = rec[2] or 0
	if n == 0 then return nil end
	local out = {}
	for k = 1, n do
		local npc, chance = rec[1 + 2 * k], rec[2 + 2 * k]
		local nrec = data.npcs[npc]
		out[k] = { id = npc, name = nrec and named("Npc", npc, nrec[1]) or nil, chance = chance }
	end
	return out
end

-- { id, name, droppers = { { id, name, chance } }, objects = { { id, name, chance } }, vendors = { { id, name } } }
function Q.GetItem(itemID)
	local rec = itemID and data.items[itemID]
	if not rec then return nil end
	local item = { id = itemID, name = named("Item", itemID, rec[1]), droppers = Q.GetItemDroppers(itemID) or {}, objects = {}, vendors = {} }
	local i = 3 + 2 * (rec[2] or 0)
	local no = rec[i] or 0
	for k = 1, no do
		local obj, chance = rec[i + 2 * k - 1], rec[i + 2 * k]
		local orec = data.objects[obj]
		item.objects[k] = { id = obj, name = orec and named("Object", obj, orec[1]) or nil, chance = chance }
	end
	for j = i + 2 * no + 1, #rec do
		local v = rec[j]
		local vrec = data.npcs[v]
		item.vendors[#item.vendors + 1] = { id = v, name = vrec and named("Npc", v, vrec[1]) or nil }
	end
	return item
end

-- Names of the mobs a quest objective is about: the kill target, or the
-- droppers of the item (best chance first). oi is the objective's position
-- in the database, which matches the quest log for nearly every quest.
function Q.GetObjectiveMobs(questID, oi)
	local r = questID and data.quests[questID]
	local obj = r and r[QUEST_OBJ]
	if not (obj and oi) then return nil end
	local i = (oi - 1) * 3 + 1
	local kind, id = obj[i], obj[i + 1]
	if kind == 1 then
		local nrec = data.npcs[id]
		return nrec and { named("Npc", id, nrec[1]) } or nil
	elseif kind == 2 then
		local d = Q.GetItemDroppers(id)
		if not d then return nil end
		local out = {}
		for k = 1, #d do
			if d[k].name then out[#out + 1] = d[k].name end
		end
		return #out > 0 and out or nil
	end
	return nil
end

---------------------------------------------------------------------------
-- Who may take a quest
---------------------------------------------------------------------------

-- Blizzard race/class bits. Era races use the low 32 bits of a race mask
-- (`races`, for bit.band); Skyborne's are 2^32 (High Order, Alliance) and
-- 2^33 (Windshaper, Horde), stored apart as `raceHigh` (+1 / +2) because
-- bit.band only covers 32 bits. Unknown new races have no bit: a mask never
-- excludes them (only the faction does).
local RACE_BIT = { Human = 1, Orc = 2, Dwarf = 4, NightElf = 8, Scourge = 16, Tauren = 32, Gnome = 64, Troll = 128 }
local SKYBORNE_HIGH = { Alliance = 1, Horde = 2 }
local CLASS_BIT = { WARRIOR = 1, PALADIN = 2, HUNTER = 4, ROGUE = 8, PRIEST = 16, SHAMAN = 64, MAGE = 128, WARLOCK = 256, DRUID = 1024 }
local FACTION_CODE = { Alliance = 1, Horde = 2 }
local band = bit and bit.band

-- { level, raceBit, raceHigh, classBit, faction (1|2|nil) } from Compat.GetPlayerInfo().
function Q.PlayerContext(info, ctx)
	ctx = ctx or {}
	info = info or ns.Compat.GetPlayerInfo()
	ctx.level = info and info.level or 1
	ctx.raceBit = info and RACE_BIT[info.race] or nil
	ctx.raceHigh = info and info.race == "Skyborne" and SKYBORNE_HIGH[info.faction] or nil
	ctx.classBit = info and CLASS_BIT[info.class] or nil
	ctx.faction = info and FACTION_CODE[info.faction] or nil
	return ctx
end

-- Highest quest level that is grey (trivial) at a player level (Classic).
function Q.GreyLevel(level)
	if level <= 5 then return 0 end
	if level <= 39 then return level - 5 - math.floor(level / 10) end
	if level <= 59 then return level - 1 - math.floor(level / 5) end
	return level - 9
end

-- Faction, race, class and holiday: what never changes for a character.
function Q.IsEligible(r, ctx)
	if r[QUEST_HOLIDAY] then return false end
	local f = r[QUEST_FACTION]
	if f and ctx.faction and f ~= ctx.faction then return false end
	local races = r[QUEST_RACES]
	if races and ctx.raceBit and band and band(races, ctx.raceBit) == 0 then return false end
	-- Skyborne: the mask's high bits (raceHigh 1 = 2^32, 2 = 2^33). Data built
	-- before raceHigh existed has none: never exclude on it.
	local high = r[QUEST_RACE_HIGH]
	if ctx.raceHigh and high and math.floor(high / ctx.raceHigh) % 2 == 0 then return false end
	local classes = r[QUEST_CLASSES]
	if classes and ctx.classBit and band and band(classes, ctx.classBit) == 0 then return false end
	return true
end

-- Whether a quest can be accepted now. isDone(q) / isOn(q) answer completion
-- and the quest log; opts.lowLevel keeps grey quests; opts.levelAbove hides
-- quests more than that many levels above the player (nil: no cap);
-- opts.skillRank(line) returns the profession rank or nil when unknowable.
-- Returns ok, reason.
function Q.CheckAvailable(id, ctx, isDone, isOn, opts)
	local r = data.quests[id]
	if not r then return false, "unknown" end
	if not Q.IsEligible(r, ctx) then return false, "eligibility" end
	if isDone(id) then return false, "done" end
	if isOn(id) then return false, "active" end
	local minLevel = r[QUEST_MIN]
	if minLevel and ctx.level < minLevel then return false, "level" end
	local level = r[QUEST_LEVEL]
	if not (opts and opts.lowLevel) and level and level > 0 and level <= Q.GreyLevel(ctx.level) then
		return false, "grey"
	end
	local above = opts and opts.levelAbove
	if above and level and level > ctx.level + above then return false, "high" end
	local preAll = r[QUEST_PRE_ALL]
	if preAll then
		for _, p in Each(preAll) do
			if not isDone(p) then return false, "prerequisite" end
		end
	end
	local pre = r[QUEST_PRE]
	if pre then
		local any = false
		for _, p in Each(pre) do
			if isDone(p) then
				any = true
				break
			end
		end
		if not any then return false, "prerequisite" end
	end
	local excl = r[QUEST_EXCL]
	if excl then
		for _, x in Each(excl) do
			if isDone(x) or isOn(x) then return false, "exclusive" end
		end
	end
	local skill = r[QUEST_SKILL]
	if skill and opts and opts.skillRank then
		local rank = opts.skillRank(skill)
		if rank ~= nil and rank <= 0 then return false, "skill" end
	end
	return true
end

-- Calls fn(q) for each quest whose done or in-log state CheckAvailable(id)
-- reads: the quest itself, its prerequisites and its exclusives. Whether the
-- quest needs a skill is returned, since the rank is read too.
local REF_KEYS = { QUEST_PRE_ALL, QUEST_PRE, QUEST_EXCL }
function Q.EachAvailabilityRef(id, fn)
	local r = data.quests[id]
	fn(id)
	if not r then return false end
	for k = 1, #REF_KEYS do
		local list = r[REF_KEYS[k]]
		if list then
			for _, q in Each(list) do fn(q) end
		end
	end
	return r[QUEST_SKILL] ~= nil
end

-- Quests whose `excl` lists id: taking id closes them. The list is one-way
-- for about one link in fifteen (282 lists 287, 287 does not list 282), so
-- this reads every record once, the first time it is asked.
local closedBy
function Q.ClosedBy(id)
	if not closedBy then
		closedBy = {}
		for _, q in ipairs(Q.QuestIds()) do
			local excl = data.quests[q][QUEST_EXCL]
			if excl then
				for _, x in Each(excl) do
					local list = closedBy[x]
					if not list then
						list = {}
						closedBy[x] = list
					end
					list[#list + 1] = q
				end
			end
		end
		for _, list in pairs(closedBy) do table.sort(list) end
	end
	return closedBy[id]
end

---------------------------------------------------------------------------
-- Client calls Compat does not offer (reported as contract gaps)
---------------------------------------------------------------------------

local client = {}
Q._client = client

-- Quest IDs in the log, in log order, into `out` (wiped). Headers skipped.
function client.LogQuestIDs(out)
	for i = #out, 1, -1 do out[i] = nil end
	local QL = C_QuestLog
	if not (QL and QL.GetNumQuestLogEntries and QL.GetInfo) then return out end
	local n = QL.GetNumQuestLogEntries() or 0
	for i = 1, n do
		local info = QL.GetInfo(i)
		if info and not info.isHeader then
			local id = ns.Compat.Readable(info.questID)
			if type(id) == "number" and id > 0 then out[#out + 1] = id end
		end
	end
	return out
end

-- Completed (flagged) quests as a set into `set` (wiped); false when the
-- client has no bulk call (then ask Compat.IsQuestCompleted per quest).
function client.CompletedSet(set)
	local QL = C_QuestLog
	if not (QL and QL.GetAllCompletedQuestIDs) then return false end
	for k in pairs(set) do set[k] = nil end
	local list = QL.GetAllCompletedQuestIDs()
	if type(list) ~= "table" then return false end
	for i = 1, #list do set[list[i]] = true end
	return true
end

---------------------------------------------------------------------------
-- Loading
---------------------------------------------------------------------------

-- Features that need the database; with all of them off it never loads.
local NEEDS = { "mapObjectives", "minimapObjectives", "availableQuests", "turnInMarkers", "questTooltips", "nameplateIcons" }

function Q.IsWanted()
	if not ns.Get("qol.questDB") then return false end
	for i = 1, #NEEDS do
		if ns.Get("qol." .. NEEDS[i]) then return true end
	end
	return false
end

-- Loads the data addon (once, through Data.Pack) when a quest feature wants
-- it. Fires QUESTDB_LOADED. Returns ok, reason ("combat": try again later).
function Q.Load()
	if data.meta then return true end
	if not Q.IsWanted() then return false, "off" end
	local _, reason = ns.Data.Pack(Q.ADDON)
	if not data.meta then
		ns.Debug("QuestDB: could not load", Q.ADDON, tostring(reason))
		return false, reason or "missing"
	end
	ns.Fire("QUESTDB_LOADED")
	return true
end
